import csv
import json


def validate_developer(developer):
    required_fields = ["name", "role", "active"]
    return all(field in developer for field in required_fields)


def import_developers(filename):
    valid = []
    invalid = []

    try:
        with open(filename, "r") as file:
            reader = csv.DictReader(file)

            for developer in reader:
                if validate_developer(developer):
                    valid.append(developer)
                else:
                    invalid.append(developer)
    except FileNotFoundError:
        return None, None

    return valid, invalid


valid, invalid = import_developers("developers.csv")

if valid is None:
    print("Developer data file not found")
else:
    with open("valid_developers.json", "w") as file:
        json.dump(valid, file, indent=2)

    report = (
        f"Total records: {len(valid) + len(invalid)}\n"
        f"Valid records: {len(valid)}\n"
        f"Invalid records: {len(invalid)}\n"
    )

    with open("import_report.txt", "w") as file:
        file.write(report)
